import subprocess
def runb(args, inp=b""):
    p = subprocess.run(["./executable"]+args, input=inp, capture_output=True)
    return p.stdout, p.stderr, p.returncode

def short(args, inp=b""):
    out,err,code = runb(args,inp)
    try: e=err.decode()
    except: e=repr(err)
    # only first 200 of out
    try: o=out.decode()
    except: o=repr(out)
    print(f"ARGS={args} CODE={code} OUT={repr(o[:300])} ERR={repr(e[:500])}")

# l variants succinct
for a in ["-l", "-lp", "-lP", "-le", "-lu", "-lPp", "-lpe", "-lpp", "-lE", "-luu", "-lpeu"]:
    out,err,code = runb([a], b"")
    try: e=err.decode()
    except: e=repr(err)
    print(f"{a}: code={code} out_lines={len(out.splitlines()) if out else 0} err={repr(e[:120])}")

# w variants
for a in ["-w5","-W5","-w0","-W0","-w9","-W9","-wx","-Wx","-w","-W","-w10","-W10","-w5x"]:
    out,err,code = runb(["+proj=merc",a], b"1 1\n")
    try: e=err.decode()
    except: e=repr(err)
    try: o=out.decode()
    except: o=repr(out)
    print(f"{a}: code={code} out={repr(o[:100])} err={repr(e[:120])}")

# combined flags
for a in ["-IE","-EI","-vE","-Ev","-sS","-Ss","-rs","-sr","-bE","-iE"]:
    out,err,code = runb(["+proj=merc",a], b"10 20\n" if "I" not in a else b"1113194.91 2258423.65\n")
    try: e=err.decode()
    except: e=repr(err)
    try: o=out.decode()
    except: o=repr(out)
